package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_nextElementSibling_TriageGen2Test {

    @Test
    public void testNextElementSibling_ReturnsNextSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a><b></b></p></div>");
        Element a = doc.selectFirst("a");
        Element b = doc.selectFirst("b");

        assertEquals("Should return the next sibling element", b, a.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_ReturnsNullWhenLastSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a></p></div>");
        Element a = doc.selectFirst("a");

        assertNull("Should return null when there is no next sibling", a.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_FirstSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a><b></b><c></c></p></div>");
        Element a = doc.selectFirst("a");
        Element b = doc.selectFirst("b");

        assertEquals(b, a.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_MiddleSibling() {
        Document doc = Parser.parseBodyFragment("<div><p><a></a><b></b><c></c></p></div>");
        Element b = doc.selectFirst("b");
        Element c = doc.selectFirst("c");

        assertEquals(c, b.nextElementSibling());
    }

    @Test(expected = NullPointerException.class)
    public void testNextElementSibling_ThrowsExceptionWhenNoParent() {
        // Creating an element not attached to a document/parent
        Element orphan = new Element(org.jsoup.parser.Tag.valueOf("div"), "");
        // In jsoup, parent() returns null if not attached. 
        // The method calls parent().children(). If parent() is null, it throws NPE.
        orphan.nextElementSibling();
    }
}
